{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Metronidazole, the closest analogue and the active parent of the query ester, has absolute oral bioavailability of 56–>100% in humans after oral doses of 500–2000 mg, directly supporting high oral bioavailability for the nitroimidazole scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Metronidazole absolute oral bioavailability was approximately 100% versus i.v. in patients, demonstrating essentially complete oral absorption for the core scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Tinidazole, a close 5-nitroimidazole analogue, has systemic availability of 96–97% in humans, supporting high oral bioavailability for this class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Secnidazole, another close 5-nitroimidazole analogue, has mean absolute oral bioavailability of 100% (±26%) in healthy volunteers, confirming the class-level high absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Levornidazole, a chiral 5-nitroimidazole analogue, has absolute oral bioavailability of 98.3% ± 7.6% in healthy subjects, further supporting high F for the query's core pharmacophore.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is metronidazole benzoate, an ester prodrug of metronidazole. The closest experimental analogues—metronidazole and other 5-nitroimidazoles—show absolute oral bioavailability near 100% in humans. The low-F dihydropyridine analogues are structurally distant and do not transfer. Therefore the query is predicted to have high oral bioavailability (F ≥ 20%).",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for metronidazole benzoate itself; ester hydrolysis and formulation effects are inferred from prodrug behavior.",
    "No human pharmacokinetic data for the exact ester moiety, though the parent drug and close analogues are consistently high."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

